import express from "express";
import path from "path";
import { GoogleGenAI } from "@google/genai";
import { createServer as createViteServer } from "vite";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json());

// Lazy initialize Gemini client
function getGeminiClient(): GoogleGenAI | null {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) return null;
  return new GoogleGenAI({
    apiKey,
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      },
    },
  });
}

// Health check endpoint
app.get("/api/health", (_req, res) => {
  res.json({
    status: "ok",
    timestamp: new Date().toISOString(),
    hasApiKey: Boolean(process.env.GEMINI_API_KEY),
  });
});

// PEA Transformer Engineering AI Consultant endpoint
app.post("/api/gemini/advisor", async (req, res) => {
  try {
    const { prompt, transformerContext } = req.body;
    if (!prompt) {
      return res.status(400).json({ error: "Missing prompt parameter" });
    }

    const ai = getGeminiClient();
    if (!ai) {
      return res.status(503).json({
        error: "GEMINI_API_KEY is not configured in server environment.",
        fallback: true,
      });
    }

    const systemInstruction = `คุณคือวิศวกรไฟฟ้าอาวุโสและผู้เชี่ยวชาญด้านมาตรฐานระบบจำหน่ายไฟฟ้าของการไฟฟ้าส่วนภูมิภาค (PEA - Provincial Electricity Authority of Thailand)
ให้คำปรึกษา แนะนำ และวิเคราะห์ข้อมูลหม้อแปลงไฟฟ้าจำหน่ายตามเกณฑ์และมาตรฐาน กฟภ. อย่างถูกต้อง แม่นยำ ชัดเจน และเป็นทางการ (เน้นวิศวกรรมปฏิบัติจริง)

เกณฑ์สำคัญของการไฟฟ้าส่วนภูมิภาค (PEA Standards):
1. แรงดันระบบจำหน่าย กฟภ.:
   - แรงสูง: 22 kV (มาตรฐานทั่วไป 3 เฟส 3 สาย หรือ 1 เฟส 2 สาย), 33 kV (พื้นที่ภาคใต้/เกาะ), 11 kV (ระบบเดิมบางพื้นที่)
   - แรงต่ำ: 400/230 V (3 เฟส 4 สาย Dyn11), 230 V (1 เฟส 2 สาย), 460/230 V (1 เฟส 3 สาย)
2. ขนาดหม้อแปลงมาตรฐาน กฟภ.:
   - 3 เฟส: 30, 50, 100, 160, 250, 315, 400, 500, 800, 1000, 1250, 1500, 2000, 2500 kVA
   - 1 เฟส: 10, 20, 30, 50 kVA (สูงสุด 50 kVA ตามมาตรฐาน กฟภ.)
3. เกณฑ์การรับโหลด (Loading Criteria):
   - โหลดปกติที่เหมาะสม: 50% - 80% (Efficiency สูงสุดและยืดอายุการใช้งาน)
   - เฝ้าระวัง (Warning): 80% - 100% (ควรวางแผนเสริมหม้อแปลงหรือเกลี่ยโหลด)
   - โหลดเกิน (Overload): > 100% (เสี่ยงฟิวส์ขาด ฉนวนเสื่อมสภาพ น้ำมันหม้อแปลงร้อนจัด)
   - ความไม่สมดุลของกระแสแต่ละเฟส (% Current Unbalance): ควรควบคุมไม่ให้เกิน 15% (วิกฤตหาก > 20%)
4. การป้องกันด้านแรงสูงใช้ **Drop-out Fuse Link Type K (Fast Link)** ตามตารางมาตรฐาน กฟภ. และด้านแรงต่ำใช้ **ฟิวส์แรงต่ำ (Low Voltage Fuse)** ประจำวงจรจ่ายไฟ:
   - หม้อแปลง 1 เฟส 22kV:
     * 10 kVA (43.5A): ฟิวส์แรงสูง 3A, ฟิวส์แรงต่ำ 1 เฟส 2 สาย = 50A
     * 20 kVA (87A): ฟิวส์แรงสูง 3A, ฟิวส์แรงต่ำ 1 เฟส 2 สาย = 100A, 1 เฟส 3 สาย = 50A
     * 30 kVA (130A): ฟิวส์แรงสูง 3A, ฟิวส์แรงต่ำ 1 เฟส 2 สาย = 160A, 1 เฟส 3 สาย = 80A
     * 50 kVA (217A): ฟิวส์แรงสูง 6A, ฟิวส์แรงต่ำ 1 เฟส 2 สาย = 200A, 1 เฟส 3 สาย = 100A
   - หม้อแปลง 3 เฟส 22kV:
     * 50 kVA (72A): ฟิวส์แรงสูง 3A, ฟิวส์แรงต่ำ 1 วงจร = 80A, 2 วงจร = 50A
     * 100 kVA (144A): ฟิวส์แรงสูง 6A, ฟิวส์แรงต่ำ 1 วงจร = 160A, 2 วงจร = 80A (หรือ 50/100, 80/80, 80/100)
     * 160 kVA (231A): ฟิวส์แรงสูง 10A, ฟิวส์แรงต่ำ 1 วงจร = 200A, 2 วงจร = 100A (หรือ 80/160, 100/100, 100/160)
     * 250 kVA (360A): ฟิวส์แรงสูง 15A, ฟิวส์แรงต่ำ 1 วงจร = 355A, 2 วงจร = 160A (หรือ 100/200, 160/160, 160/200, 200/200)
     * 315 kVA: ฟิวส์แรงสูง 15A
     * 400 kVA: ฟิวส์แรงสูง 20A
     * 500 kVA: ฟิวส์แรงสูง 20A
     * 630 kVA: ฟิวส์แรงสูง 25A
     * 800 kVA: ฟิวส์แรงสูง 30A
     * 1000 kVA: ฟิวส์แรงสูง 40A
     * 1250 kVA: ฟิวส์แรงสูง 50A
     * 2000 kVA: ฟิวส์แรงสูง 65A
   - สูตรคำนวณ:
     * ระบบ 1 เฟส: ฟิวส์แรงสูง = kVA / kV, ฟิวส์แรงต่ำ = kVA / 230
     * ระบบ 3 เฟส: ฟิวส์แรงสูง = kVA / (1.732 * kV), ฟิวส์แรงต่ำ = kVA / (1.732 * 400)
5. การชดเชยกำลังไฟฟ้ารีแอกทีฟด้วย Capacitor Bank (เป้าหมาย Power Factor >= 0.85 หรือ 0.90 ตามระเบียบ กฟภ.)
6. การรองรับโหลดสถานีชาร์จยานยนต์ไฟฟ้า (EV Charging Station - AC 7.4/22 kW, DC Fast Charge)

ตอบด้วยภาษาไทยที่สุภาพ กระชับ เป็นขั้นเป็นตอน และเน้นการแก้ปัญหาหน้างานจริง`;

    const contents = transformerContext
      ? `[ข้อมูลหม้อแปลงและสถานะโหลดปัจจุบัน]\n${JSON.stringify(transformerContext, null, 2)}\n\n[คำถาม/โจทย์จากผู้ใช้งาน]\n${prompt}`
      : prompt;

    const response = await ai.models.generateContent({
      model: "gemini-3.7-flash",
      contents,
      config: {
        systemInstruction,
        temperature: 0.4,
      },
    });

    const replyText = response.text || "ไม่มีข้อความตอบกลับจากระบบ";
    return res.json({ reply: replyText });
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    return res.status(500).json({
      error: error.message || "เกิดข้อผิดพลาดในการประมวลผล AI",
    });
  }
});

async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`PEA Transformer Load Server running on http://localhost:${PORT}`);
  });
}

startServer();
